<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
$admin=require_admin($pdo);if(!admin_support_ready($pdo)){http_response_code(503);exit('Admin V2.20 Support Operations requires migration 075.');}
admin_access_assert_capability($pdo,$admin,'admin.support.view');$canManage=admin_access_has_capability($pdo,$admin,'admin.support.manage');$success='';$error='';$created=null;
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{
    if(!$canManage)throw new RuntimeException('Your operator role cannot manage support cases.');
    $op=(string)($_POST['op']??'');
    if($op==='create'){$created=admin_support_create($pdo,$admin,$_POST);$success='Support case created.';}
    elseif($op==='save_view'){admin_support_saved_view_save($pdo,$admin,(string)($_POST['view_name']??''),$_POST,!empty($_POST['is_default']));$success='Support view saved.';}
    elseif($op==='delete_view'){admin_support_saved_view_delete($pdo,$admin,(string)($_POST['view_id']??''));$success='Saved support view deleted.';}
    else throw new RuntimeException('Unknown Support Operations action.');
}catch(Throwable $e){$error=$e->getMessage();}}
$filters=admin_support_filters($_GET);$dashboard=admin_support_dashboard($pdo,$admin,$filters);$cases=$dashboard['cases'];$metrics=$dashboard['metrics'];$operators=$dashboard['operators'];$views=$dashboard['views'];$categories=$dashboard['categories'];$workload=$dashboard['workload'];$effective=$dashboard['filters'];
$accounts=admin_ui_account_rows($pdo,[],300);
