<main class="panel adminSupportPage"><div class="pageTitle"><span class="eyebrow">ADMIN V2.20 · SUPPORT OPERATIONS</span><h1>Support inbox & customer service workspace</h1><p>Work customer cases from one queue with account context, SLA risk, ownership, communications, escalation and resolution history. Commercial and security source systems remain authoritative.</p></div>
<?php if($success):?><div class="success"><?=h($success)?><?php if($created):?> <a href="/admin/support-case.php?id=<?=h(rawurlencode((string)$created['public_id']))?>">Open <?=h((string)$created['public_id'])?></a><?php endif?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<section class="adminDashboardMetrics">
<a class="card adminMetric" href="/admin/support.php"><span>Open cases</span><strong><?=h(number_format((int)($metrics['open']??0)))?></strong></a>
<a class="card adminMetric" href="/admin/support.php?assigned=me"><span>My cases</span><strong><?=h(number_format((int)($metrics['mine']??0)))?></strong></a>
