<div class="tableWrap"><table><thead><tr><th>Case</th><th>Customer</th><th>Priority</th><th>Status</th><th>Owner</th><th>SLA</th><th>Updated</th></tr></thead><tbody><?php foreach($cases as $case):$slaRisk=!in_array($case['status'],['resolved','closed'],true)&&!empty($case['sla_due_at'])&&strtotime((string)$case['sla_due_at'])<=time()+14400;?><tr><td><a href="/admin/support-case.php?id=<?=h(rawurlencode((string)$case['public_id']))?>"><strong><?=h((string)$case['title'])?></strong></a><div class="meta"><?=h((string)$case['public_id'])?> · <?=h((string)$case['category'])?></div></td><td><?=h((string)($case['account_name']?:($case['customer_display_name']?:($case['customer_username']?:'Unlinked'))))?><?php if($case['customer_email']):?><div class="meta"><?=h((string)$case['customer_email'])?></div><?php endif?></td><td><span class="badge"><?=h(strtoupper((string)$case['priority']))?></span></td><td><?=h(ucwords(str_replace('_',' ',(string)$case['status'])))?><?php if($case['duplicate_of_case_id']):?><div class="meta">Duplicate</div><?php endif?></td><td><?=h((string)($case['assigned_display_name']?:($case['assigned_username']?:'Unassigned')))?></td><td class="<?=$slaRisk?'dangerText':''?>"><?=h((string)($case['sla_due_at']?:'—'))?><?=$slaRisk?' · RISK':''?></td><td><?=h((string)$case['updated_at'])?></td></tr><?php endforeach?><?php if(!$cases):?><tr><td colspan="7" class="empty">No support cases match this view.</td></tr><?php endif?></tbody></table></div></section>
<?php if($canManage):?><section class="card"><div class="sectionHeadWeb"><div><span class="eyebrow">NEW CASE</span><h2>Create support case</h2></div></div><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="op" value="create"><div class="adminAccountTwoCol"><label>Account<select name="account_public_id"><option value="">Optional / resolve from user</option><?php foreach($accounts as $a):?><option value="<?=h((string)$a['public_id'])?>" <?=((string)($_GET['account']??'')===(string)$a['public_id'])?'selected':''?>><?=h((string)$a['name'])?> · <?=h((string)$a['public_id'])?></option><?php endforeach?></select></label><label>User<input name="user_identifier" placeholder="username, email or user ID"></label></div><label>Title<input name="title" required maxlength="255" value="<?=h((string)($_GET['new_title']??''))?>" placeholder="Customer cannot access billing portal"></label><div class="adminAccountTwoCol"><label>Category<input name="category" maxlength="80" value="<?=h((string)($_GET['category']??'general'))?>" placeholder="billing, access, ai_usage"></label><label>Priority<select name="priority"><option value="normal">Normal · 24h SLA</option><option value="high">High · 8h SLA</option><option value="urgent">Urgent · 4h SLA</option><option value="low">Low · 72h SLA</option></select></label></div><label>Assign to<select name="assigned_user_id"><option value="">Leave unassigned</option><?php foreach($operators as $op):?><option value="<?=h((string)$op['id'])?>"><?=h((string)($op['display_name']?:$op['username']))?></option><?php endforeach?></select></label><label>Internal description<textarea name="description" required rows="4" maxlength="1000" placeholder="What is the customer reporting, and what evidence do we have?"></textarea></label><button>Create support case</button></form></section><?php endif?>
